// Constant fallback (median |breakaway| per direction), signed by convention.
#define STICTION_EXTEND_CONST_MN   4694.429f
#define STICTION_RETRACT_CONST_MN  -5522.575f

// Signed breakaway force (mN) at position, for direction = +1 (extend) or
// -1 (retract). Uniform-grid index + linear interpolation; clamps to the ends.
static inline float stiction_lookup_mN(float pos_um, int direction) {
  const float* tbl = (direction >= 0) ? STICTION_EXTEND_MN : STICTION_RETRACT_MN;
  float span = (float)(STICTION_POS_MAX_UM - STICTION_POS_MIN_UM);
  float f = (pos_um - (float)STICTION_POS_MIN_UM) / span
            * (float)(STICTION_N_NODES - 1);
  if (f <= 0.0f) return tbl[0];
  if (f >= (float)(STICTION_N_NODES - 1)) return tbl[STICTION_N_NODES - 1];
  int i = (int)f;
  float frac = f - (float)i;
  return tbl[i] + frac * (tbl[i + 1] - tbl[i]);
}

// Constant-fallback variant (select via a runtime flag in Parts B/C).
static inline float stiction_const_mN(int direction) {
  return (direction >= 0) ? STICTION_EXTEND_CONST_MN : STICTION_RETRACT_CONST_MN;
}

